"""Turning readings into the numbers the pages show."""
from bikecount import events


def daily_totals(readings):
    """Total per calendar day, oldest first."""
    days = {}
    for r in readings:
        day = r.when.date()
        days[day] = days.get(day, 0) + r.total
    return sorted(days.items())


def busiest_day(readings):
    """The day with the most people, and its count."""
    return max(daily_totals(readings), key=lambda kv: kv[1])


def yearly_summary(readings):
    """Total, average day and busiest day for each calendar year, oldest first.

    Each entry is (year, total, average day, busiest day, busiest day's count).
    The average leaves out event days (storms, holidays), so one snowbound
    Monday doesn't drag down what an ordinary day looks like. It's otherwise
    over days that are actually in the file, so a partial year at either end
    of the data isn't averaged down over months it doesn't cover. The total
    still counts every day, event days included.
    """
    days_by_year = {}
    for day, count in daily_totals(readings):
        days_by_year.setdefault(day.year, []).append((day, count))
    summary = []
    for year, days in sorted(days_by_year.items()):
        total = sum(count for _, count in days)
        busiest_day, busiest_count = max(days, key=lambda kv: kv[1])
        normal_days = [count for day, count in days if not events.label(day)]
        avg = round(sum(normal_days) / max(len(normal_days), 1))
        summary.append((year, total, avg, busiest_day, busiest_count))
    return summary


def monthly_totals(readings):
    """Total per calendar month, oldest first. Each key is the first of the month."""
    months = {}
    for r in readings:
        month = r.when.date().replace(day=1)
        months[month] = months.get(month, 0) + r.total
    return sorted(months.items())


def hourly_averages(readings):
    """Average count for each hour of the day, 0 to 23, midnight first.

    Readings from event days (storms, holidays) are left out, so a snowbound
    Monday doesn't pull down what an ordinary hour looks like.
    """
    totals = {}
    counts = {}
    for r in readings:
        if events.label(r.when.date()):
            continue
        hour = r.when.hour
        totals[hour] = totals.get(hour, 0) + r.total
        counts[hour] = counts.get(hour, 0) + 1
    return sorted((hour, round(totals[hour] / counts[hour])) for hour in totals)


def hourly_averages_weekday(readings):
    """Same as hourly_averages, Monday to Friday only."""
    return hourly_averages(r for r in readings if r.when.weekday() < 5)


def hourly_averages_weekend(readings):
    """Same as hourly_averages, Saturday and Sunday only."""
    return hourly_averages(r for r in readings if r.when.weekday() >= 5)


def side_totals(readings):
    """Total bikes counted on the east and west sidewalks."""
    east = sum(r.east for r in readings)
    west = sum(r.west for r in readings)
    return east, west


def hourly_west_share(readings):
    """West sidewalk's share of the total, as a percent, for each hour of day.

    Higher than 50 means west carries more than east at that hour; lower
    means east does. East's share is just 100 minus this.
    """
    east = {}
    west = {}
    for r in readings:
        hour = r.when.hour
        east[hour] = east.get(hour, 0) + r.east
        west[hour] = west.get(hour, 0) + r.west
    return sorted((hour, round(100 * west[hour] / (east[hour] + west[hour]))) for hour in east)


def west_share_by_year(readings):
    """West sidewalk's share of the total, as a percent, for each calendar year.

    Same idea as hourly_west_share, but by year, to check whether the split
    between the two sides is stable over time or drifting.
    """
    east = {}
    west = {}
    for r in readings:
        year = r.when.year
        east[year] = east.get(year, 0) + r.east
        west[year] = west.get(year, 0) + r.west
    return sorted((year, round(100 * west[year] / (east[year] + west[year]))) for year in east)

